function TopicMap($t,$s){
 $lines=$t -split "`r?`n"; $times=[System.Collections.Generic.List[string]]::new(); foreach($line in $lines){$v=$line.Trim(); if($v -match '^\d{2}:\d{2}:\d{2}$'){$times.Add($v)}}
 $sections=[System.Collections.Generic.List[string]]::new(); $x=$s -split "`r?`n"; for($i=0;$i -lt $x.Count;$i++){ $v=$x[$i].Trim(); if($v -match '^Next steps$'){break}; if($v -match '^[A-Z][A-Za-z0-9 &’''()-]{2,75}$' -and $v -notmatch '^(Summary|Details|Decisions|Aligned|Sofia session|Charles session|Ore|Asia|Yahunathan session|LSAT Session.*)$'){$sections.Add($v)}}
 $body=[System.Collections.Generic.List[string]]::new(); $body.Add('# Topic map'); $body.Add(''); $body.Add('Generated from the source transcript timecodes and Gemini summary headings.'); $body.Add(''); if($sections.Count){$body.Add('## Source summary topics'); $body.Add(''); foreach($a in $sections | Select-Object -Unique){$body.Add('- '+$a)}}; if($times.Count){$body.Add('');$body.Add('## Transcript timecodes');$body.Add('');$body.Add('The transcript provides these time markers without topic labels:');$body.Add('');$body.Add(($times | Select-Object -Unique | ForEach-Object {'- '+$_}))};return $body -join "`n"
}
$spec=@(
@{s='sofia';d='2026-09-04';label='parallel-reasoning'},@{s='sofia';d='2026-09-09';label='smacker-causal-reasoning'},@{s='sofia';d='2026-09-11';label='conditional-reasoning'},@{s='sofia';d='2026-09-15';label='conditional-sufficient-assumptions'},@{s='sofia';d='2026-09-18';label='sufficient-assumptions'},@{s='sofia';d='2026-09-23';label='preptest-and-conditionals'},@{s='charles-moore';d='2026-09-03';label='argument-analysis'},@{s='charles-moore';d='2026-09-14';label='conditional-logic'},@{s='ore';d='2026-09-11';label='argument-structure'},@{s='asia';d='2026-08-25';label='conditional-logic'},@{s='avneet-natt';d='2026-09-08';label='necessary-assumptions'},@{s='yahunatan-zetvy';d='2026-09-02';label='conditional-logic'},@{s='yahunatan-zetvy';d='2026-09-16';label='conditional-logic-and-theology'}
)
foreach($x in $spec){$pkg="students/$($x.s)/sessions/$($x.d)-$($x.label)";New-Item -ItemType Directory -Force -Path $pkg | Out-Null; $tf="temp_transcript_$($x.s)_$($x.d).txt";$sf="temp_summary_$($x.s)_$($x.d).txt"; $t=Get-Content $tf -Raw; $s=Get-Content $sf -Raw; if(-not $t -or -not $s){Write-Output "SKIP missing source: $pkg"; continue}; Set-Content -LiteralPath "$pkg/transcript.md" -Value $t -NoNewline -Encoding utf8; Set-Content -LiteralPath "$pkg/summary.md" -Value $s -NoNewline -Encoding utf8; $map=TopicMap $t $s; Set-Content -LiteralPath "$pkg/topic-map.md" -Value $map -Encoding utf8; "created $pkg"}
